/// Parse a document in a subset of JSON and return it in canonical form, or
/// None if the document is invalid.
/// The document is exactly one value, optionally surrounded by whitespace.
/// Values: objects {"key": value, ...}, arrays [value, ...], strings, integers,
/// true, false and null. Whitespace (space, tab, newline, carriage return) may
/// appear before and after any value, comma, colon or bracket.
/// - Strings are enclosed in double quotes. A raw newline inside a string is
///   invalid. The only escapes are \" \\ \/ \n and \t; any other escape
///   (\u included) is invalid.
/// - Integers: an optional '-', then one or more ASCII digits with no leading
///   zero unless the digits are exactly "0" ("-0" is valid, "01" is not).
///   Fractions and exponents are invalid.
/// - Object keys are strings. Two keys that are equal after decoding escapes
///   make the document invalid. Trailing commas are invalid.
/// - Anything after the value other than whitespace is invalid; so is an empty
///   or all-whitespace document.
/// Canonical form: no whitespace at all; integers in plain decimal ("-0" becomes
/// "0"); object members sorted by decoded key, in ascending character-code
/// order; strings re-encoded with exactly these escapes: '"' as \", '\' as
/// \\, newline as \n and tab as \t ('/' is written plainly).
/// >>> canonical_json(String::from(r#" { "b" : [1, -0, "x\/y"], "a": {} } "#))
/// Some(String::from(r#"{"a":{},"b":[1,0,"x/y"]}"#))
/// >>> canonical_json(String::from("[1, 2,]"))
/// None
fn canonical_json(text: String) -> Option<String> {
    let cs: Vec<char> = text.chars().collect();
    let mut pos = 0;
    let v = json_value(&cs, &mut pos)?;
    json_ws(&cs, &mut pos);
    if pos == cs.len() { Some(v) } else { None }
}

fn json_ws(cs: &[char], pos: &mut usize) {
    while *pos < cs.len() && " \t\n\r".contains(cs[*pos]) {
        *pos += 1;
    }
}

fn json_expect(cs: &[char], pos: &mut usize, c: char) -> Option<()> {
    json_ws(cs, pos);
    if *pos < cs.len() && cs[*pos] == c {
        *pos += 1;
        Some(())
    } else {
        None
    }
}

fn json_string(cs: &[char], pos: &mut usize) -> Option<String> {
    json_expect(cs, pos, '"')?;
    let mut out = String::new();
    while *pos < cs.len() && cs[*pos] != '"' {
        let mut c = cs[*pos];
        if c == '\n' {
            return None;
        }
        if c == '\\' {
            c = match cs.get(*pos + 1) {
                Some('"') => '"',
                Some('\\') => '\\',
                Some('/') => '/',
                Some('n') => '\n',
                Some('t') => '\t',
                _ => return None,
            };
            *pos += 1;
        }
        out.push(c);
        *pos += 1;
    }
    json_expect(cs, pos, '"')?;
    Some(out)
}

fn json_encode(s: &str) -> String {
    let body = s.replace('\\', "\\\\").replace('"', "\\\"").replace('\n', "\\n").replace('\t', "\\t");
    format!("\"{}\"", body)
}

fn json_value(cs: &[char], pos: &mut usize) -> Option<String> {
    json_ws(cs, pos);
    let c = *cs.get(*pos).unwrap_or(&'\0');
    if c == '{' || c == '[' {
        let close = if c == '{' { '}' } else { ']' };
        *pos += 1;
        let mut items: Vec<(String, String)> = Vec::new();
        json_ws(cs, pos);
        if cs.get(*pos) == Some(&close) {
            *pos += 1;
        } else {
            loop {
                if c == '{' {
                    let key = json_string(cs, pos)?;
                    json_expect(cs, pos, ':')?;
                    items.push((key, json_value(cs, pos)?));
                } else {
                    items.push((String::new(), json_value(cs, pos)?));
                }
                json_ws(cs, pos);
                if cs.get(*pos) == Some(&',') {
                    *pos += 1;
                    continue;
                }
                json_expect(cs, pos, close)?;
                break;
            }
        }
        if c == '[' {
            let vals: Vec<String> = items.into_iter().map(|(_, v)| v).collect();
            return Some(format!("[{}]", vals.join(",")));
        }
        items.sort();
        if items.windows(2).any(|w| w[0].0 == w[1].0) {
            return None;
        }
        let members: Vec<String> = items.iter().map(|(k, v)| format!("{}:{}", json_encode(k), v)).collect();
        return Some(format!("{{{}}}", members.join(",")));
    }
    if c == '"' {
        return Some(json_encode(&json_string(cs, pos)?));
    }
    for word in ["true", "false", "null"] {
        let w: Vec<char> = word.chars().collect();
        if cs[*pos..].starts_with(&w) {
            *pos += w.len();
            return Some(word.to_string());
        }
    }
    let start = *pos;
    if c == '-' {
        *pos += 1;
    }
    let digits = *pos;
    while *pos < cs.len() && cs[*pos].is_ascii_digit() {
        *pos += 1;
    }
    if *pos == digits || (cs[digits] == '0' && *pos - digits > 1) {
        return None;
    }
    let n: i64 = cs[start..*pos].iter().collect::<String>().parse().ok()?;
    Some(n.to_string())
}
